<section id="karier" class="py-12 md:py-14 bg-white border-b border-slate-200/80" aria-labelledby="career-heading">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        <!-- Header -->
        <div class="flex flex-col md:flex-row md:items-end justify-between mb-8 gap-5">
            <div class="max-w-3xl">
                <span class="inline-block text-xs font-bold uppercase tracking-wider text-[#155EAA] mb-2">
                    Program Vokasi Internasional
                </span>
                <h2 id="career-heading" class="text-2xl sm:text-3xl md:text-4xl font-extrabold text-[#0F2F5F] tracking-tight">
                    Karir Global untuk Masa Depan
                </h2>
                <p class="mt-3 text-sm text-slate-600 leading-relaxed">
                    SMKN 7 Jember mendesain ekosistem pembinaan komprehensif dari hulu ke hilir untuk memastikan siswa memiliki daya saing unggul, legalitas terjamin, dan perlindungan penuh selama berkarier di Jepang.
                </p>
            </div>
            <div>
                <button type="button" 
                        onclick="window.openCareerProgramModal()" 
                        class="inline-flex items-center gap-2 px-6 py-3.5 rounded-xl bg-[#0F2F5F] hover:bg-[#155EAA] text-white text-xs sm:text-sm font-bold shadow-md hover:shadow-lg transition-all transform hover:-translate-y-0.5 cursor-pointer">
                    <span>Jelajahi Program</span>
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                </button>
            </div>
        </div>

        <!-- 5 Core Program Pillars Grid -->
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4 mb-10 items-stretch">
            <div class="h-full p-4 rounded-2xl bg-slate-50 border border-slate-200/80 hover:border-[#155EAA]/50 hover:bg-blue-50/20 transition-all card-hover-lift group flex flex-col">
                <div class="w-10 h-10 rounded-xl bg-blue-100 text-[#155EAA] flex items-center justify-center font-bold mb-3 group-hover:scale-105 transition-transform"><svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg></div>
                <h3 class="text-sm font-bold text-slate-900 group-hover:text-[#155EAA] transition-colors mb-2">Peluang Kerja & Magang di Jepang</h3>
                <p class="text-xs sm:text-[13px] text-slate-600 leading-relaxed">Akses ke skema Tokutei Ginou dan Magang Industri di Jepang. Program mencakup standar gaji, asuransi kesehatan, dan akomodasi yang layak.</p>
                <div class="mt-auto pt-3 border-t border-slate-200/60 text-xs font-semibold text-[#155EAA] flex items-center gap-1"><span>Manufaktur, Agribisnis & Hospitality</span></div>
            </div>
            <div class="h-full p-4 rounded-2xl bg-slate-50 border border-slate-200/80 hover:border-[#166534]/50 hover:bg-emerald-50/20 transition-all card-hover-lift group flex flex-col">
                <div class="w-10 h-10 rounded-xl bg-emerald-100 text-[#166534] flex items-center justify-center font-bold mb-3 group-hover:scale-105 transition-transform"><svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"/></svg></div>
                <h3 class="text-sm font-bold text-slate-900 group-hover:text-[#166534] transition-colors mb-2">Pelatihan Bahasa & Budaya Jepang</h3>
                <p class="text-xs sm:text-[13px] text-slate-600 leading-relaxed">Pembelajaran JLPT N5–N4 dan JFT-Basic dilengkapi budaya kerja 5S, Kaizen, disiplin waktu, serta etika Hou-Ren-So.</p>
                <div class="mt-auto pt-3 border-t border-slate-200/60 text-xs font-semibold text-[#166534] flex items-center gap-1"><span>Instruktur Berpengalaman & Native</span></div>
            </div>
            <div class="h-full p-4 rounded-2xl bg-slate-50 border border-slate-200/80 hover:border-[#d97706]/50 hover:bg-amber-50/20 transition-all card-hover-lift group flex flex-col">
                <div class="w-10 h-10 rounded-xl bg-amber-100 text-[#d97706] flex items-center justify-center font-bold mb-3 group-hover:scale-105 transition-transform"><svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg></div>
                <h3 class="text-sm font-bold text-slate-900 group-hover:text-[#d97706] transition-colors mb-2">Pendampingan Dokumen & Legalitas</h3>
                <p class="text-xs sm:text-[13px] text-slate-600 leading-relaxed">Pendampingan paspor, Certificate of Eligibility (COE), visa, dan verifikasi kontrak kerja. Setiap tahap membantu memastikan dokumen keberangkatan tertata.</p>
                <div class="mt-auto pt-3 border-t border-slate-200/60 text-xs font-semibold text-[#d97706] flex items-center gap-1"><span>Jaminan Legalitas & Transparansi</span></div>
            </div>
            <div class="h-full p-4 rounded-2xl bg-slate-50 border border-slate-200/80 hover:border-purple-600/50 hover:bg-purple-50/20 transition-all card-hover-lift group flex flex-col">
                <div class="w-10 h-10 rounded-xl bg-purple-100 text-purple-700 flex items-center justify-center font-bold mb-3 group-hover:scale-105 transition-transform"><svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"/></svg></div>
                <h3 class="text-sm font-bold text-slate-900 group-hover:text-purple-700 transition-colors mb-2">Persiapan Keberangkatan & Kebugaran</h3>
                <p class="text-xs sm:text-[13px] text-slate-600 leading-relaxed">Persiapan pra-penerbangan, kemandirian finansial, dan kebutuhan musim dingin. Kesehatan peserta dipantau melalui MCU berkala.</p>
                <div class="mt-auto pt-3 border-t border-slate-200/60 text-xs font-semibold text-purple-700 flex items-center gap-1"><span>Pembekalan Mental & Kebugaran Fisik</span></div>
            </div>
            <div class="h-full p-4 rounded-2xl bg-gradient-to-r from-blue-900/10 via-slate-50 to-slate-50 border border-slate-200/80 hover:border-[#0F2F5F]/50 transition-all card-hover-lift group flex flex-col justify-between">
                <div><div class="w-10 h-10 rounded-xl bg-[#0F2F5F] text-white flex items-center justify-center font-bold mb-3 group-hover:scale-105 transition-transform"><svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg></div>
                    <h3 class="text-sm font-bold text-slate-900 group-hover:text-[#0F2F5F] transition-colors mb-2">Dukungan Jejaring Alumni & Mitra Asosiasi Penerima</h3>
                    <p class="text-xs sm:text-[13px] text-slate-600 leading-relaxed">Peserta didik mendapat dukungan komunitas alumni SMKN 7 Jember dan asosiasi mitra di Jepang. Mereka membantu penyambutan, orientasi domisili, dan pendaftaran asuransi lokal.</p></div>
                <div class="mt-auto pt-3 border-t border-slate-200/60 text-xs font-semibold text-[#0F2F5F] flex items-center gap-2"><span class="w-2 h-2 rounded-full bg-emerald-500"></span><span>Jejaring Aktif di Tokyo, Nagoya, Osaka, Shizuoka & Kanagawa</span></div>
            </div>
        </div>
        <!-- 5-Stage Roadmap Process Section -->
        <div class="bg-slate-50 rounded-3xl p-5 sm:p-6 lg:p-7 border border-slate-200/80">
            <div class="text-center max-w-2xl mx-auto mb-6">
                <span class="text-xs font-bold text-[#155EAA] uppercase tracking-wider">Langkah Bertahap</span>
                <h3 class="text-xl sm:text-2xl font-extrabold text-[#0F2F5F] mt-1">Alur Perjalanan Program Go Global</h3>
                <p class="text-xs sm:text-sm text-slate-600 mt-2">Dari bangku sekolah hingga menapaki lantai industri di Jepang melalui proses terukur.</p>
            </div>

            <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3 relative">
                <div aria-hidden="true" class="absolute left-[13px] top-4 bottom-4 w-px bg-slate-300 lg:left-[10%] lg:right-[10%] lg:top-4 lg:bottom-auto lg:h-px lg:w-auto"></div>
                
                <!-- Step 1 -->
                <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs relative">
                    <span class="w-7 h-7 rounded-full bg-[#0F2F5F] text-white flex items-center justify-center font-bold text-xs mb-2 lg:mx-auto">1</span>
                    <h4 class="text-xs font-bold text-slate-900 mb-1 lg:text-center">Sosialisasi & Seleksi Minat</h4>
                    <p class="text-[11px] text-slate-500 leading-relaxed">Pengenalan program, tes bakat kejuruan, dan persetujuan wali murid.</p>
                </div>

                <!-- Step 2 -->
                <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs relative">
                    <span class="w-7 h-7 rounded-full bg-[#155EAA] text-white flex items-center justify-center font-bold text-xs mb-2 lg:mx-auto">2</span>
                    <h4 class="text-xs font-bold text-slate-900 mb-1 lg:text-center">Diklat Bahasa & Budaya</h4>
                    <p class="text-[11px] text-slate-500 leading-relaxed">Pelatihan intensif JLPT N4/N5, kanji, etika Kaizen, dan kedisiplinan 5S.</p>
                </div>

                <!-- Step 3 -->
                <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs relative">
                    <span class="w-7 h-7 rounded-full bg-[#166534] text-white flex items-center justify-center font-bold text-xs mb-2 lg:mx-auto">3</span>
                    <h4 class="text-xs font-bold text-slate-900 mb-1 lg:text-center">Wawancara Mitra Industri</h4>
                    <p class="text-[11px] text-slate-500 leading-relaxed">Simulasi wawancara kerja langsung dengan delegasi perusahaan Jepang.</p>
                </div>

                <!-- Step 4 -->
                <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs relative">
                    <span class="w-7 h-7 rounded-full bg-amber-600 text-white flex items-center justify-center font-bold text-xs mb-2 lg:mx-auto">4</span>
                    <h4 class="text-xs font-bold text-slate-900 mb-1 lg:text-center">MCU & Penerbitan Visa</h4>
                    <p class="text-[11px] text-slate-500 leading-relaxed">Pemeriksaan medis standar MHLW dan pemrosesan COE serta visa kedutaan.</p>
                </div>

                <!-- Step 5 -->
                <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs relative">
                    <span class="w-7 h-7 rounded-full bg-purple-700 text-white flex items-center justify-center font-bold text-xs mb-2 lg:mx-auto">5</span>
                    <h4 class="text-xs font-bold text-slate-900 mb-1 lg:text-center">Pelepasan & Tiba di Jepang</h4>
                    <p class="text-[11px] text-slate-500 leading-relaxed">Pelepasan resmi sekolah, penyambutan mitra, dan adaptasi tempat kerja.</p>
                </div>

            </div>
        </div>

    </div>
</section>
